// src/App.js — effect phụ thuộc [userId] + cờ ignore chống phản hồi cũ đè phản hồi mới
import { useEffect, useState } from 'react';

export default function App() {
  const [userId, setUserId] = useState(1);
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let ignore = false;
    setLoading(true);
    fetch(`http://localhost:9999/posts?userId=${userId}`)
      .then((r) => r.json())
      .then((data) => {
        if (!ignore) {
          setPosts(data);
          setLoading(false);
        }
      });
    return () => {
      ignore = true; // effect cũ bị huỷ ⇒ bỏ qua phản hồi của nó
    };
  }, [userId]);

  return (
    <div>
      <select id="user" value={userId} onChange={(e) => setUserId(Number(e.target.value))}>
        <option value="1">User 1</option>
        <option value="2">User 2</option>
      </select>
      {loading ? (
        <p id="loading">Loading...</p>
      ) : (
        <>
          <p id="post-count">User {userId} has {posts.length} posts</p>
          <ul>{posts.map((p) => <li key={p.id} className="post">{p.title}</li>)}</ul>
        </>
      )}
    </div>
  );
}

