// src/App.js — interval trong effect phụ thuộc [running], cleanup xoá interval
import { useEffect, useState } from 'react';

export default function App() {
  const [seconds, setSeconds] = useState(3);
  const [left, setLeft] = useState(3);
  const [running, setRunning] = useState(false);

  useEffect(() => {
    if (!running) return undefined;
    const id = setInterval(() => setLeft((s) => s - 1), 1000);
    return () => clearInterval(id);
  }, [running]);

  useEffect(() => {
    if (left <= 0) setRunning(false);
  }, [left]);

  const start = () => {
    if (running) return; // đang chạy ⇒ không tạo thêm
    if (left <= 0 || left > seconds) setLeft(seconds);
    setRunning(true);
  };

  return (
    <div>
      <input id="seconds" type="number" min="1" value={seconds} onChange={(e) => { setSeconds(Number(e.target.value)); setLeft(Number(e.target.value)); }} />
      <button id="btn-start" type="button" onClick={start}>Start</button>
      <button id="btn-pause" type="button" onClick={() => setRunning(false)}>Pause</button>
      <p id="display">{left <= 0 ? "Time's up!" : left}</p>
    </div>
  );
}

