// src/App.js — lỗi định dạng tính ngay; kiểm trùng tên debounce 500 ms bằng effect + clearTimeout
import { useEffect, useState } from 'react';

function formatError(name) {
  if (name.length < 3) return 'At least 3 characters';
  if (!/^[A-Za-z0-9]+$/.test(name)) return 'Letters and digits only';
  return null;
}

export default function App() {
  const [username, setUsername] = useState('');
  const [status, setStatus] = useState('idle'); // idle | checking | taken | available
  const error = username ? formatError(username) : null;

  useEffect(() => {
    if (!username || formatError(username)) {
      setStatus('idle');
      return undefined;
    }
    setStatus('checking');
    let ignore = false;
    const id = setTimeout(async () => {
      const res = await fetch(`http://localhost:9999/users?username=${encodeURIComponent(username)}`);
      const list = await res.json();
      if (!ignore) setStatus(list.length ? 'taken' : 'available');
    }, 500);
    return () => {
      ignore = true;
      clearTimeout(id); // gõ tiếp ⇒ huỷ lần kiểm trước
    };
  }, [username]);

  const TEXT = { checking: 'Checking...', taken: 'Username is taken', available: 'Username is available' };
  const message = error || TEXT[status] || '';

  return (
    <div>
      <input id="username" value={username} onChange={(e) => setUsername(e.target.value.trim())} />
      <p id="message">{message}</p>
      <button id="btn-register" type="button" disabled={status !== 'available' || !!error}>Register</button>
    </div>
  );
}
